{
  "devices": [
    {
      "device": "bio_shake",
      "existing_tags": [
        {
          "id": "4313",
          "name": "实验执行&合成设备",
          "name_en": "Experiment Execution & Synthesis Equipment",
          "type": "experimental_step",
          "rationale": "用于在设定温度下对微孔板进行振荡混匀与孵育，直接服务于反应/孵育等实验执行环节。"
        },
        {
          "id": "4318",
          "name": "生命体系",
          "name_en": "Life Sciences",
          "type": "experimental_domain",
          "rationale": "常用于酶促反应、孵育与样品制备等生命科学微孔板流程。"
        },
        {
          "id": "4319",
          "name": "溶液配制与反应",
          "name_en": "Solution Preparation & Reaction",
          "type": "experimental_domain",
          "rationale": "支持对孔板内溶液进行恒温振荡混匀，适配溶液体系的混合与反应孵育。"
        },
        {
          "id": "4330",
          "name": "细胞生物学研究",
          "name_en": "Cell Biology Research",
          "type": "experimental_scene",
          "rationale": "可用于微孔板孵育与混匀，常见于细胞相关板式实验与培养/处理流程。"
        },
        {
          "id": "4421",
          "name": "热混匀仪",
          "name_en": "Thermomixer",
          "type": "device_template_tag",
          "rationale": "设备集加热控温与振荡混匀于一体，功能与热混匀仪/恒温振荡混匀设备一致。"
        }
      ],
      "proposed_new_tags": []
    },
    {
      "device": "cc_core",
      "existing_tags": [
        {
          "id": "4313",
          "name": "实验执行&合成设备",
          "name_en": "Experiment Execution & Synthesis Equipment",
          "type": "experimental_step",
          "rationale": "作为量子实验的中央时序与序列控制器，用于运行序列程序并分发同步触发，属于实验执行与控制环节。"
        }
      ],
      "proposed_new_tags": [
        {
          "id": "P-0001",
          "name": "量子测控与时序控制",
          "name_en": "Quantum Measurement & Timing Control",
          "type": "experimental_domain",
          "rationale": "设备核心用途为量子实验的确定性时序、触发同步与数字链路校准，现有领域标签缺少量子测控方向。"
        },
        {
          "id": "P-0002",
          "name": "超导量子比特实验",
          "name_en": "Superconducting Qubit Experiments",
          "type": "experimental_scene",
          "rationale": "说明中明确提到常用于超导量子比特等实验系统的时序控制与联机诊断。"
        },
        {
          "id": "P-0003",
          "name": "中央时序与序列控制器",
          "name_en": "Central Timing & Sequencing Controller",
          "type": "device_template_tag",
          "rationale": "设备为可运行硬件序列程序并通过数字I/O模块分发同步触发的中央控制器，现有模板标签未覆盖该类仪器。"
        }
      ]
    },
    {
      "device": "cryo_tel_gt",
      "existing_tags": [
        {
          "id": "4313",
          "name": "实验执行&合成设备",
          "name_en": "Experiment Execution & Synthesis Equipment",
          "type": "experimental_step",
          "rationale": "为冷台/低温组件提供冷量并稳温到设定值，是低温实验运行时的关键执行与保障设备。"
        }
      ],
      "proposed_new_tags": [
        {
          "id": "P-0004",
          "name": "低温制冷与低温实验支撑",
          "name_en": "Cryogenic Cooling & Cryogenic Experiment Support",
          "type": "experimental_domain",
          "rationale": "设备为闭循环低温制冷机并支持温度/功率模式控制，现有领域标签缺少低温制冷与低温实验支撑类目。"
        },
        {
          "id": "P-0005",
          "name": "低温平台与冷台稳温",
          "name_en": "Cryogenic Platform & Cold-Stage Temperature Stabilization",
          "type": "experimental_scene",
          "rationale": "用于冷台/低温组件的温度稳定与状态监测，匹配低温平台稳温这一典型应用场景。"
        },
        {
          "id": "P-0006",
          "name": "闭循环低温制冷机",
          "name_en": "Closed-Cycle Cryocooler",
          "type": "device_template_tag",
          "rationale": "CryoTel GT为闭循环制冷设备（含控制器），提供低温冷量与稳温控制，现有模板标签未包含低温制冷机类型。"
        }
      ]
    },
    {
      "device": "cvd_control",
      "existing_tags": [
        {
          "id": "4313",
          "name": "实验执行&合成设备",
          "name_en": "Experiment Execution & Synthesis Equipment",
          "type": "experimental_step",
          "rationale": "用于执行CVD工艺配方步骤、控制反应腔温度与多路气体流量，是沉积实验的工艺执行系统。"
        },
        {
          "id": "4322",
          "name": "表面/薄膜体系",
          "name_en": "Surface / Thin Film System",
          "type": "experimental_domain",
          "rationale": "CVD属于典型薄膜沉积工艺，设备用于薄膜工艺参数设定与过程控制。"
        },
        {
          "id": "4349",
          "name": "二维材料",
          "name_en": "2D Materials",
          "type": "experimental_scene",
          "rationale": "二维材料常采用CVD生长/沉积工艺，该控制系统用于CVD配方与气体/温控执行。"
        },
        {
          "id": "4348",
          "name": "有机光伏材料（OPV和OLED）",
          "name_en": "Organic Photovoltaic Materials (OPV & OLED)",
          "type": "experimental_scene",
          "rationale": "薄膜材料研究常涉及受控沉积过程；该系统面向薄膜沉积的配方执行与趋势监控。"
        },
        {
          "id": "4373",
          "name": "化学气相沉积设备",
          "name_en": "Chemical Vapor Deposition System",
          "type": "device_template_tag",
          "rationale": "系统用于CVD实验的温控、MFC流量设定与配方执行，属于CVD设备体系中的关键控制部分。"
        }
      ],
      "proposed_new_tags": [
        {
          "id": "P-0007",
          "name": "CVD工艺控制系统",
          "name_en": "CVD Process Control System",
          "type": "device_template_tag",
          "rationale": "该设备描述强调配方步骤执行、气体流量设定/监控与温控联动，区别于整机CVD设备，需独立模板标签以准确标注。"
        }
      ]
    },
    {
      "device": "cytomat_backend",
      "existing_tags": [
        {
          "id": "4315",
          "name": "器件/细胞设备",
          "name_en": "Device / Cell Equipment",
          "type": "experimental_step",
          "rationale": "在受控温度与CO₂/O₂/湿度环境中进行板式培养/孵育，直接服务于细胞相关实验设备范畴。"
        },
        {
          "id": "4317",
          "name": "物流/机械",
          "name_en": "Logistics / Machinery",
          "type": "experimental_step",
          "rationale": "具备内部搬运机构与对外传递工位，实现微孔板自动存取与转运，属于自动化物流搬运环节。"
        },
        {
          "id": "4318",
          "name": "生命体系",
          "name_en": "Life Sciences",
          "type": "experimental_domain",
          "rationale": "主要用于细胞培养、反应孵育与样品暂存等生命科学自动化流程。"
        },
        {
          "id": "4330",
          "name": "细胞生物学研究",
          "name_en": "Cell Biology Research",
          "type": "experimental_scene",
          "rationale": "支持CO₂/O₂/湿度控制的培养箱式微孔板存储与孵育，典型应用为细胞培养与板式孵育。"
        },
        {
          "id": "4334",
          "name": "移液站产品",
          "name_en": "Liquid Handling Station Products",
          "type": "experimental_scene",
          "rationale": "设备支持与机械臂/自动化产线联机，实现微孔板暂存与供给，常与移液工作站组成自动化流水线。"
        },
        {
          "id": "4442",
          "name": "组织培养试验箱",
          "name_en": "Tissue Culture Chamber",
          "type": "device_template_tag",
          "rationale": "维持温度与气体环境（如CO₂、O₂、湿度）以进行培养/孵育，具备培养箱核心功能。"
        },
        {
          "id": "4446",
          "name": "自动化耗材堆栈",
          "name_en": "Automated Consumable Stack",
          "type": "device_template_tag",
          "rationale": "具备内部货架/仓位并自动存取微孔板，功能类似自动化堆栈式存储与取放系统。"
        }
      ],
      "proposed_new_tags": [
        {
          "id": "P-0008",
          "name": "自动化培养箱式微孔板存储系统",
          "name_en": "Automated Incubator Microplate Storage System",
          "type": "device_template_tag",
          "rationale": "Cytomat为带培养环境控制与自动存取/传递机构的“微孔板酒店”，现有模板标签无法完整覆盖其“培养+存储+转运”一体化特征。"
        }
      ]
    }
  ]
}

